window.docContents[249].resolve({"/Lecture-1___-Motivation-and-Propositional-Logic/Natural-Deduction/#Formal-Software-Verification--Lecture-1___-Motivation-and-Propositional-Logic--Natural-Deduction--Conjunction":{"contents":"To introduce P ∧ Q, prove both conjuncts. Elimination projects either conjunct.\n\n   P    Q              P ∧ Q            P ∧ Q\n  ───────  ∧I         ───────  ∧E₁     ───────  ∧E₂\n   P ∧ Q                 P                Q\n\n\n","context":"Formal Software Verification\u0009Lecture 1: Motivation and Propositional Logic\u0009Natural Deduction","header":"1.5.2. Conjunction","id":"/Lecture-1___-Motivation-and-Propositional-Logic/Natural-Deduction/#Formal-Software-Verification--Lecture-1___-Motivation-and-Propositional-Logic--Natural-Deduction--Conjunction"},"/Lecture-1___-Motivation-and-Propositional-Logic/Natural-Deduction/#Formal-Software-Verification--Lecture-1___-Motivation-and-Propositional-Logic--Natural-Deduction--Disjunction":{"contents":"To introduce P ∨ Q, prove one disjunct. To eliminate it, prove a common conclusion R from each disjunct in turn, discharging the disjunct assumed in each branch.\n\n     P                 Q                              [P]     [Q]\n  ───────  ∨I₁      ───────  ∨I₂          P ∨ Q         ⋮       ⋮\n   P ∨ Q             P ∨ Q                              R       R\n                                        ──────────────────────────  ∨E\n                                                     R\n\n\n","context":"Formal Software Verification\u0009Lecture 1: Motivation and Propositional Logic\u0009Natural Deduction","header":"1.5.3. Disjunction","id":"/Lecture-1___-Motivation-and-Propositional-Logic/Natural-Deduction/#Formal-Software-Verification--Lecture-1___-Motivation-and-Propositional-Logic--Natural-Deduction--Disjunction"}});